private static string GetTrainingLevelID(DataRow row)
{
    if (row == null || row.Table == null)
        return "";

    if (!row.Table.Columns.Contains("TrainingLevelID"))
        return "";

    if (row["TrainingLevelID"] == null || row["TrainingLevelID"] == DBNull.Value)
        return "";

    return row["TrainingLevelID"].ToString().Trim();
}

